  ddl('HDR_COMMANDS_KEY_IX', 'CREATE INDEX HDR_COMMANDS_KEY_IX ON HDR_COMMANDS (SN, CONTENT_KEY)');
  -- the checks of the last minutes or the last day (heartbeat, punch, clock, arrows that turn): a range of the
