-- ---------------------------------------------------------------- hdr_triggers.sql
CREATE OR REPLACE TRIGGER HDR_EMPLOYEES_SYNC
AFTER INSERT OR UPDATE OR DELETE ON HDR_EMPLOYEES FOR EACH ROW
BEGIN
  IF HDR_CORE.g_quiet THEN
    RETURN;
  END IF;
  IF DELETING THEN
    HDR_CORE.mark_pending('EMP', :OLD.EMP_CODE, p_deleted => TRUE);
  ELSIF INSERTING OR NVL(:OLD.FULL_NAME, '~') <> NVL(:NEW.FULL_NAME, '~') OR NVL(:OLD.CARD_NO, '~') <> NVL(:NEW.CARD_NO, '~')
        OR NVL(:OLD.DEV_PASSWORD, '~') <> NVL(:NEW.DEV_PASSWORD, '~') OR :OLD.DEV_PRIVILEGE <> :NEW.DEV_PRIVILEGE
        OR :OLD.VERIFY_MODE <> :NEW.VERIFY_MODE OR :OLD.STATUS <> :NEW.STATUS THEN
    HDR_CORE.mark_pending('EMP', :NEW.EMP_CODE);
  END IF;
  -- hire / leaving dates and the switch for attendance change which days are calculated: from the earlier
  -- of the old and new dates (the days now outside employment are dropped), at least this month
  IF UPDATING AND (NVL(:OLD.HIRE_DATE, DATE '1900-01-01') <> NVL(:NEW.HIRE_DATE, DATE '1900-01-01')
                   OR NVL(:OLD.RESIGN_DATE, DATE '1900-01-01') <> NVL(:NEW.RESIGN_DATE, DATE '1900-01-01')
                   OR :OLD.STATUS <> :NEW.STATUS OR :OLD.ENABLE_ATT <> :NEW.ENABLE_ATT
                   OR NVL(:OLD.DEPT_CODE, '~') <> NVL(:NEW.DEPT_CODE, '~')) THEN
    HDR_CORE.mark_days(:NEW.EMP_CODE, LEAST(TRUNC(SYSDATE, 'MM'),
      CASE WHEN NVL(:OLD.HIRE_DATE, DATE '1900-01-01') <> NVL(:NEW.HIRE_DATE, DATE '1900-01-01')
                OR :OLD.ENABLE_ATT <> :NEW.ENABLE_ATT
           THEN LEAST(NVL(:OLD.HIRE_DATE, DATE '1900-01-01'), NVL(:NEW.HIRE_DATE, DATE '1900-01-01')) ELSE SYSDATE END,
      CASE WHEN NVL(:OLD.RESIGN_DATE, DATE '1900-01-01') <> NVL(:NEW.RESIGN_DATE, DATE '1900-01-01')
                OR :OLD.STATUS <> :NEW.STATUS
           THEN LEAST(NVL(:OLD.RESIGN_DATE, SYSDATE), NVL(:NEW.RESIGN_DATE, SYSDATE)) ELSE SYSDATE END), SYSDATE);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_EMP_AREAS_SYNC
AFTER INSERT OR UPDATE OR DELETE ON HDR_EMP_AREAS FOR EACH ROW
BEGIN
  IF HDR_CORE.g_quiet THEN
    RETURN;
  END IF;
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_pending('EMP', :OLD.EMP_CODE, p_removed => TO_CHAR(:OLD.AREA_ID));
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_pending('EMP', :NEW.EMP_CODE, p_added => TO_CHAR(:NEW.AREA_ID));
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_DEVICES_SYNC
AFTER UPDATE OF AREA_ID, ENABLED ON HDR_DEVICES FOR EACH ROW
BEGIN
  IF NOT HDR_CORE.g_quiet AND :NEW.ENABLED = 'Y'
     AND (NVL(:OLD.AREA_ID, -1) <> NVL(:NEW.AREA_ID, -1) OR :OLD.ENABLED <> :NEW.ENABLED) THEN
    HDR_CORE.mark_pending('DEV', :NEW.SN);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_LEAVES_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HDR_LEAVES FOR EACH ROW
BEGIN
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_days(:OLD.EMP_CODE, :OLD.START_TIME, :OLD.END_TIME - 1 / 86400);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_days(:NEW.EMP_CODE, :NEW.START_TIME, :NEW.END_TIME - 1 / 86400);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_OVERTIME_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HDR_OVERTIME FOR EACH ROW
BEGIN
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_days(:OLD.EMP_CODE, :OLD.START_TIME - 1, :OLD.END_TIME);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_days(:NEW.EMP_CODE, :NEW.START_TIME - 1, :NEW.END_TIME);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_MANUAL_PUNCHES_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HDR_MANUAL_PUNCHES FOR EACH ROW
BEGIN
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_dirty(:OLD.EMP_CODE, :OLD.PUNCH_TIME);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_dirty(:NEW.EMP_CODE, :NEW.PUNCH_TIME);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_TEMP_SCHEDULES_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HDR_TEMP_SCHEDULES FOR EACH ROW
BEGIN
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_dirty(:OLD.EMP_CODE, :OLD.ATT_DATE);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_dirty(:NEW.EMP_CODE, :NEW.ATT_DATE);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_SCHEDULES_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HDR_SCHEDULES FOR EACH ROW
BEGIN
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_days(:OLD.EMP_CODE, :OLD.START_DATE, :OLD.END_DATE);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_days(:NEW.EMP_CODE, :NEW.START_DATE, :NEW.END_DATE);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_PUNCHES_DAYS
AFTER INSERT OR UPDATE OR DELETE ON HADER_PUNCHES FOR EACH ROW
BEGIN
  IF HDR_CORE.g_quiet OR NOT HDR_JOBS.active THEN   -- still the Hader program's table: nothing to calculate yet
    RETURN;
  END IF;
  IF DELETING OR UPDATING THEN
    HDR_CORE.mark_dirty(:OLD.EMP_CODE, :OLD.PUNCH_TIME);
  END IF;
  IF INSERTING OR UPDATING THEN
    HDR_CORE.mark_dirty(:NEW.EMP_CODE, :NEW.PUNCH_TIME);
  END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_HOLIDAYS_ALL
AFTER INSERT OR UPDATE OR DELETE ON HDR_HOLIDAYS FOR EACH ROW
BEGIN
  HDR_CORE.mark_pending('ALL', 'ALL', p_from => LEAST(NVL(:OLD.START_DATE, :NEW.START_DATE), NVL(:NEW.START_DATE, :OLD.START_DATE)));
END;
/
CREATE OR REPLACE TRIGGER HDR_DEPT_SCHEDULES_ALL
AFTER INSERT OR UPDATE OR DELETE ON HDR_DEPT_SCHEDULES FOR EACH ROW
BEGIN
  HDR_CORE.mark_pending('ALL', 'ALL', p_from => LEAST(NVL(:OLD.START_DATE, :NEW.START_DATE), NVL(:NEW.START_DATE, :OLD.START_DATE)));
END;
/
CREATE OR REPLACE TRIGGER HDR_TIMETABLES_ALL
AFTER INSERT OR UPDATE OR DELETE ON HDR_TIMETABLES
BEGIN
  HDR_CORE.mark_pending('ALL', 'ALL', p_from => TRUNC(SYSDATE, 'MM'));
END;
/
CREATE OR REPLACE TRIGGER HDR_SHIFTS_ALL
AFTER INSERT OR UPDATE OR DELETE ON HDR_SHIFTS
BEGIN
  HDR_CORE.mark_pending('ALL', 'ALL', p_from => TRUNC(SYSDATE, 'MM'));
END;
/
CREATE OR REPLACE TRIGGER HDR_SHIFT_DAYS_ALL
AFTER INSERT OR UPDATE OR DELETE ON HDR_SHIFT_DAYS
BEGIN
  HDR_CORE.mark_pending('ALL', 'ALL', p_from => TRUNC(SYSDATE, 'MM'));
END;
/
CREATE OR REPLACE TRIGGER HDR_SETTINGS_ALL
AFTER INSERT OR UPDATE ON HDR_SETTINGS FOR EACH ROW
WHEN (NEW.SKEY LIKE 'att.%')
BEGIN
  IF NVL(:OLD.SVALUE, '~') <> NVL(:NEW.SVALUE, '~') THEN
    HDR_CORE.mark_pending('ALL', 'ALL', p_from => TRUNC(SYSDATE, 'MM'));
  END IF;
END;
/

-- ---------------------------------------------------------------- hdr_scheduler.sql
BEGIN
  BEGIN
    DBMS_SCHEDULER.DROP_JOB('HDR_TICK', force => TRUE);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE <> -27475 THEN
      RAISE;
    END IF;
  END;
  DBMS_SCHEDULER.CREATE_JOB(
    job_name        => 'HDR_TICK',
    job_type        => 'PLSQL_BLOCK',
    job_action      => 'BEGIN HDR_JOBS.tick; END;',
    start_date      => SYSTIMESTAMP,
    repeat_interval => 'FREQ=MINUTELY;INTERVAL=1',
    enabled         => TRUE,
    comments        => 'Hader: terminals, attendance calculation, HR import, requests');
END;
/

-- ---------------------------------------------------------------- done
DECLARE
  n NUMBER;
BEGIN
  MERGE INTO HDR_SETTINGS t USING (SELECT 'maintenance' k FROM DUAL) s ON (t.SKEY = s.k)
  WHEN MATCHED THEN UPDATE SET SVALUE = 'N' WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, 'N');
  BEGIN
    EXECUTE IMMEDIATE 'BEGIN HDR_CORE.set_setting(''schema.version'', HDR_CORE.c_version); END;';
  EXCEPTION WHEN OTHERS THEN
    NULL;   -- HDR_CORE does not compile: counted below
  END;
  COMMIT;
  SELECT COUNT(*) INTO n FROM user_errors WHERE name LIKE 'HDR%' OR name LIKE 'HADER%';
  DBMS_OUTPUT.PUT_LINE('Hader for Oracle APEX: ' || n || ' compile errors (workshop/3_verify.sql lists them)');
END;
/
